INSERT INTO t_p65760950_mystery_box_initiati.articles_db
  (author_id, slug, title, lead, category, image_url, content, status, read_time, published_at)
VALUES
(
  1,
  'yamal-nenets',
  'Ненцы Ямала: как живут люди, которые никогда не останавливаются',
  'Каждый год они проходят тысячи километров по тундре с оленьими стадами. Не потому что вынуждены — потому что так устроена их жизнь. Это не кочевничество. Это философия.',
  'Люди',
  'https://cdn.poehali.dev/projects/0fd730b6-ff99-47c2-a8cd-b94909d66811/files/d7d519aa-1291-4bb6-b21f-f7a95e2d4e92.jpg',
  '[{"type":"text","value":"На Ямале живёт около 29 000 ненцев. Примерно треть из них — тундровые ненцы, которые ведут кочевой образ жизни, практически не изменившийся за тысячи лет. Каждую весну они уходят на север, каждую осень — возвращаются на юг. Это называется «путь»."},{"type":"heading","value":"Чум: дом, который собирается за час"},{"type":"text","value":"Чум — конический шатёр из жердей, покрытый оленьими шкурами. Его ставят и разбирают несколько раз в год. Опытная хозяйка ставит чум за 40–60 минут. Внутри — тепло даже при минус сорока: печка-«буржуйка», нюки из шкур, сундуки с вещами. Всё продумано до сантиметра."},{"type":"quote","value":"В чуме нет ничего лишнего. Всё, что не нужно — оставляешь. Это учит не привязываться к вещам."},{"type":"image","value":"https://cdn.poehali.dev/projects/0fd730b6-ff99-47c2-a8cd-b94909d66811/files/39cf37d6-a60b-4d5f-aef6-ace75eb480ac.jpg","caption":"Оленевод Ямальского района на традиционном нарте"},{"type":"heading","value":"Олень — это всё"},{"type":"text","value":"Для ненцев олень — это еда, транспорт, одежда и жильё одновременно. Шкура идёт на чум и малицу (меховую одежду), мясо едят, рога используют в орудиях. Ненцы говорят: «Нет оленей — нет человека». Сегодня ямальские ненцы держат около 700 000 голов — крупнейшее в мире поголовье домашних оленей."},{"type":"text","value":"При этом ненцы активно используют современные технологии: снегоходы, спутниковые телефоны, интернет. Молодёжь учится в интернатах в посёлках и возвращается в тундру. «Нам не нужно выбирать между прошлым и будущим», — говорит 25-летний Иван Яптик, пастух в четвёртом поколении."}]',
  'published',
  9,
  NOW()
),
(
  1,
  'yamal-tundra',
  'Ямал: край земли, где небо занимает всё',
  'Полуостров Ямал — одно из самых труднодоступных мест России. Здесь нет дорог, зато есть тысячи озёр, северное сияние и ощущение, что ты на самом краю мира.',
  'Места',
  'https://cdn.poehali.dev/projects/0fd730b6-ff99-47c2-a8cd-b94909d66811/files/66d70005-26f2-4658-a1be-8c0c5c62aac3.jpg',
  '[{"type":"text","value":"«Ямал» в переводе с ненецкого означает «край земли». И это не преувеличение: полуостров вдаётся в Карское море почти на 700 километров. Зимой здесь бывает минус 50, летом — не больше плюс 20. Но главное — это свет. Или его отсутствие."},{"type":"heading","value":"Полярная ночь и белые ночи"},{"type":"text","value":"В Салехарде — единственном городе мира на Полярном круге — зимой солнце не встаёт больше месяца. Зато летом оно не заходит почти два месяца. Местные привыкают: у окон — плотные шторы, в голове — свой внутренний календарь. Приезжие сходят с ума от белых ночей в первые же дни."},{"type":"image","value":"https://cdn.poehali.dev/projects/0fd730b6-ff99-47c2-a8cd-b94909d66811/files/c232d721-8357-4021-b691-ca705d6d495c.jpg","caption":"Северное сияние над Салехардом, декабрь 2025"},{"type":"quote","value":"Первое северное сияние — это шок. Потом — зависимость. Потом — понимаешь, что без этого уже не можешь."},{"type":"heading","value":"Как добраться"},{"type":"text","value":"На Ямал нет дороги с материка. Летом — только паром через Обь или самолёт. Зимой — ледовая переправа, которая работает два-три месяца. Это делает Ямал одним из самых изолированных регионов России и — парадоксально — одним из самых нетронутых."}]',
  'published',
  7,
  NOW()
),
(
  1,
  'yamal-food',
  'Строганина и оленина: кухня Ямала, которую нельзя придумать',
  'Ненецкая кухня — это не рецепты. Это способ выжить в тундре и при этом есть вкусно. Строганина, варёная оленина, ягоды морошки — здесь всё честно и без лишнего.',
  'Кухня',
  'https://cdn.poehali.dev/projects/0fd730b6-ff99-47c2-a8cd-b94909d66811/files/fa0b2269-574c-4603-bb87-c6b5205223a3.jpg',
  '[{"type":"text","value":"Ненецкая кухня формировалась тысячи лет в условиях, когда привезти продукты было невозможно. Поэтому всё — местное: олень, рыба, ягоды, птица. Никаких специй, никакой обработки ради вкуса. Только то, что есть."},{"type":"heading","value":"Строганина"},{"type":"text","value":"Строганина — замороженная сырая рыба или мясо, нарезанные тонкими стружками прямо из мороза. Чаще всего это нельма, муксун или щёкур. Едят с солью, иногда с перцем. Никакой термообработки. Для неподготовленного человека это кажется странным — пока не попробуешь. Вкус — чистый, ледяной, без лишнего."},{"type":"quote","value":"Строганина — это не экзотика для туриста. Это завтрак охотника, который вышел в мороз на рассвете."},{"type":"heading","value":"Оленина"},{"type":"text","value":"Оленина — основа рациона. Варят, вялят, коптят, едят сырой. Ненцы особо ценят свежую кровь только что забитого оленя — говорят, она лучше любого витаминного комплекса. Это не дикость: в условиях полного отсутствия свежих овощей кровь действительно спасала от цинги."},{"type":"text","value":"Сегодня ямальская кухня входит в моду по всей России. В Салехарде открываются рестораны со строганиной и ухой из муксуна. Шефы из Москвы едут на Ямал за вдохновением. Но сами ненцы по-прежнему готовят так, как готовили их предки — просто потому что так вкуснее."}]',
  'published',
  6,
  NOW()
);